import json,hashlib
p='/workspace/scratch/volume4/batch409-418.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(413,[
('يبقى في صاحب هذه الجمعية موضع للإشارة؛ لأن جمعيته على المطلوب المراد أغنته عن الإشارة إليه. وأيضا فإن جمعيته أفنته عن نفسه وإشارته، ففي مقام الفناء تنقطع الإشارة لأنها من أحكام البشرية.', 'у обладателя этой сосредоточенности не остаётся места для указания: сосредоточенность на Искомом и Желаемом избавляет его от нужды указывать на Него. Кроме того, сосредоточенность погружает его в фана по отношению к самому себе и своему указанию. На стоянке фана указание прекращается, поскольку относится к проявлениям человеческой природы».'),
('قوله: «وشخص عن الماء والطين». هذا يحتمل معنيين:', 'Его слова «и возвысилось над водой и глиной» допускают два смысла.'),
('أحدهما: أن يريد بالماء والطين بني آدم، ونفسه من جملتهم. أي شخص عن النظر إلى الناس والالتفات إليهم وتعلق القلب بهم بالكلية. وخصهم بالذكر لأن أكثر العلائق وأصعبها وأشدها قطعا لصاحبها هي علائقهم، فإذا شخص قلبه عنهم بالكلية، فعن غيرهم ممن هو أبعد إليه منهم أولى وأحرى.', 'Первый: под водой и глиной он подразумевает сынов Адама, включая себя самого. То есть человек совершенно отрешился от взирания на людей, обращения внимания на них и привязанности к ним сердца. Люди особо упомянуты потому, что большая часть привязанностей, самые трудные и сильнее всего прерывающие путь их обладателя, — это привязанности к ним. Если сердце полностью отрешилось от них, то тем более оно отрешится от других вещей, которые ему ещё более далеки.'),
('وفي ذكر الماء والطين تقرير لهذا الشخوص عنهم، وتنبيه على تعينه ووجوبه، فإن المخلوق من الماء والطين بشر ضعيف، لا يملك لنفسه ـ ولا لمن تعلق به ـ جلب منفعة ولا دفع مضرة، فإن الماء والطين منفعل لا فعال، وعاجز مهين لا قوي متين، كما قال تعالى: {فاستفتهم أهم أشد خلقا أم من خلقنا إنا خلقناهم من طين لازب} [الصافات: ١١]، وأخبر أنه خلقنا {من ماء مهين} [السجدة: ٨]. فتحقيق ابن الماء والطين: أن يشخص عنه القلب، لا إليه؛ وأن يعول على خالقه وحده، لا عليه؛ وأن يجعل رغبته كلها فيه وفيما لديه.', 'Упоминание воды и глины подтверждает необходимость такого отрешения от людей и указывает на то, что оно обязательно. Сотворённый из воды и глины — слабый человек, неспособный ни самому себе, ни тому, кто к нему привязался, принести пользу или отвести вред. Вода и глина испытывают воздействие, а не действуют сами; они бессильны и ничтожны, а не сильны и крепки. Всевышний сказал: {فاستفتهم أهم أشد خلقا أم من خلقنا إنا خلقناهم من طين لازب} — «Спроси же их: их ли труднее сотворить или тех, кого Мы сотворили? Поистине, Мы сотворили их из липкой глины» [37:11]. И сообщил, что сотворил нас {من ماء مهين} — «из презренной жидкости» [32:8]. Подлинное понимание сына воды и глины состоит в том, чтобы сердце отрешилось от него, а не устремлялось к нему, опиралось на одного лишь его Творца, а не на него и обращало всё своё желание к Нему и к тому, что у Него.'),
('المعنى الثاني الذي يحتمله كلامه: أن يشخص عن أحكام الطبيعة السفلية الناشئة من الماء والطين وعن متعلقاتها إلى أحكام الأرواح العلوية.', 'Второй возможный смысл его слов — возвыситься от проявлений низшей природы, происходящей из воды и глины, и связанных с нею вещей к проявлениям высших духов.'),
('والله سبحانه ـ بحكمته وعجيب صنعه ـ جعل الإنسان مركبا من جوهرين: جوهر طبيعي كثيف وهو الجسم، وجوهر روحاني لطيف وهو', 'Пречистый Аллах по Своей мудрости и дивному творению составил человека из двух субстанций: плотной природной субстанции — тела и тонкой духовной субстанции —')])
page(414,[
('الروح، ومن شأن كل شكل أن يميل إلى شكله، ومن طبع كل مثل أن ينجذب إلى مثله = صار الإنسان ينجذب إلى العالم الطبيعي بما فيه من الكثافة، وإلى العالم الروحاني بما فيه من اللطافة؛ فصارت في الإنسان قوتان متضادتان إحداهما: تجذبه سفلا، والثانية: تجذبه علوا. فمن شخص عن طبيعة الماء والطين إلى محل الأرواح العلوية التي ليست من هذا العالم السفلي كان من أهل هذا الجمع المحمود الذي جمعه عن متفرقات النفس والطبع.', 'духа. Всякое подобное склоняется к подобному, всякое сходное по природе тянется к сходному. Поэтому человек притягивается к природному миру своей плотностью и к духовному миру — своей тонкостью. В нём оказываются две противоположные силы: одна влечёт его вниз, другая — вверх. Тот, кто возвысился над природой воды и глины к обители высших духов, не принадлежащих этому низшему миру, принадлежит к людям похвальной собранности: она собрала его, избавив от того, что рассеивает душу и природное естество.'),
('قوله: «بعد صحة التمكين، والبراءة من التلوين، والخلاص من شهود الثنوية». معناه: أن العبد لا يمكنه أن يشخص عن الماء والطين إلا بعد صحة تمكنه في المعرفة، وبراءته من التلوين. فشرط الشيخ حصول التمكين له، وانتفاء التلوين عنه، وخلاصه من شهود الثنوية.', 'Его слова «после подлинного утверждения, освобождения от переменчивости и избавления от созерцания двойственности» означают: раб способен возвыситься над водой и глиной лишь после того, как прочно утвердится в познании и освободится от переменчивости. Шейх поставил условия: обретение утверждённости, отсутствие переменчивости и избавление от созерцания двойственности.'),
('فالتلوين: تلونه لإجابة دواعي الطبع والنفس. وشهود الثنوية: عبارة مجملة محتملة، وقد حملها الملحد على أنه يشهد عبدا وربا، وقديما وحادثا، وخالقا ومخلوقا. والتوحيد المحض: أن يتخلص من ذلك بشهود وحدة الوجود، ومتى شهد تعدد الوجود كان ثنويا عند الملاحدة.', 'Переменчивость — это изменение его состояния в ответ на побуждения природного естества и души. «Созерцание двойственности» — неопределённое и допускающее разные смыслы выражение. Безбожник истолковал его как созерцание раба и Господа, Предвечного и возникшего, Творца и творения. По его мнению, чистое единобожие — избавиться от этого, созерцая единство бытия. Кто созерцает множественность бытия, тот для безбожников — дуалист.')])
page(415,[
('وأما الموحدون، فالثنوية التي يجب التخلص منها: أن يتخذ إلهين اثنين، فيشهد مع الله إلها آخر. وأما كونه شهد مع الله موجودا غيره هو موجده وخالقه وفاطره، فليس بثنوية، بل توحيد خالص. ولا يتم له التوحيد إلا بهذا الشهود ليصلح له نفي الإلهية عنه، وإلا فكيف ينفي الإلهية عما لا يشهده ويشهد نفيها عنه؟', 'Для людей единобожия двойственность, от которой необходимо избавиться, — это признать двух богов и созерцать наряду с Аллахом другого бога. Что же касается созерцания вместе с Аллахом другого существующего, которому Он дал бытие, которого сотворил и создал изначально, это не дуализм, а чистое единобожие. Единобожие человека не будет полным без этого созерцания, позволяющего отрицать божественность за этим иным. Как иначе он станет отрицать божественность за тем, чего не созерцает, и созерцать отсутствие у него божественности?'),
('والمقصود: أن صاحب الجمع إذا شهد ربا وعبدا، وخالقا ومخلوقا، وآمرا وفاعلا منفذا، ومحركا ومتحركا، ووليا وعدوا = كان ذلك موجب عقد التوحيد.', 'Итак, когда человек собранности созерцает Господа и раба, Творца и творение, Повелевающего и исполнителя Его повеления, Движущего и движущееся, приближённого и врага, это необходимо следует из утверждённого единобожия.'),
('وصحة التمكين: هي حفظ الأصل الذي هو بقاء شهود الرسوم في مرتبتها. وكأنه رحمه الله نبه بذلك على الاحتراز من القوم الذين تخطفهم لوائح شهود الجمع وتمكنهم ضعيف، فينكرون صور الخلق، حتى يقول أحدهم: أنا نور من نور ربي، لما يغلب على أحدهم من شهود الجمع، وعدم تمكنه في البقاء.', 'Подлинная утверждённость — это сохранение основы: созерцание сотворённых обликов остаётся на своём месте. По-видимому, этими словами он, да помилует его Аллах, предостерегает от людей, которых уносят вспышки созерцания собранности, тогда как их утверждённость слаба. Они отрицают облики творений, и один из них доходит до слов: «Я — свет от света моего Господа». Так происходит из-за того, что созерцание собранности возобладало в нём, а в пребывании он не утвердился.'),
('وهذا قد يعرض للصادق أحيانا، فيعلم أنه غالط، فيرجع إلى الأصل، ويحكم العلم على الحال. فإذا صحا علم أنه كان غالطا مخطئا. وفي مثل هذه', 'Это иногда случается и с правдивым человеком, но он понимает, что заблуждается, возвращается к основе и подчиняет состояние суду знания. Протрезвев, он узнаёт, что заблуждался и ошибался. В подобном')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
